const pack=()=>readProject(new Blob([readFileSync(new URL('../public/library/Mr.Kille.hahmo',import.meta.url))]));
async function fixture(){const r=await pack(),assets={kille:{doc:r.doc,animation:r.animation}},voice={name:'voice.wav',blob:new Blob([new Uint8Array(44)],{type:'audio/wav'})};let p=parsePresentation('Kohtaus: cutout-studio-v1\nLAAJA KUVA\nKILLE:\n“Hello.”\nPidä 0,5 sekuntia hiljaisuutta.\nPUOLIKUVA\nKILLE:\n“Goodbye.”');p.natural=true;p.bindings=[{speaker:'KILLE',asset:'kille',voice:'own',side:'left',functions:Object.fromEntries(functions.map(f=>[f,f==='show_phone'?'none':'supported']))}];p.audioClips=p.events.filter(e=>e.kind==='dialogue').map((e,i)=>({id:'voice-'+i,dialogue:e.id,asset:'audio-'+i,start:0,end:1,duration:1,source:'viseme',mouth:[{time:0,shape:'open',viseme:'AI'},{time:1,shape:'rest',viseme:'REST'}]}));p=compilePresentation(p,assets,24);return{r,assets,state:{model:p,voices:{'audio-0':voice,'audio-1':voice}} as ProductionState,voice};}
test('episode/scene/shot identity survives timing and presentation metadata edits',async()=>{const {state}=await fixture(),a=adaptPresentation(state.model),b=adaptPresentation({...state.model,metadata:{...state.model.metadata,title:'Changed'},seconds:4});assert.equal(a.id,b.id);assert.deepEqual(a.shots.map(s=>s.id),b.shots.map(s=>s.id));assert.equal(a.timebase,TIMEBASE);assert.ok(a.scenes.every(s=>s.episodeId===a.id));assert.equal(seconds(ticks(1001/30000)),1001/30000);assert.throws(()=>ticks(-1));assert.throws(()=>readStudio({schemaVersion:1,episodeId:'x',revision:0}));});
test('audio replacement is atomic, retimes following shots, regenerates mouths and invalidates approval; undo restores voices and timing',async()=>{const {state,voice,assets}=await fixture(),before=state.model,episode=adaptPresentation(before);before.production??=initProduction(before);before.production.studio={...studioMetadata(before),shots:{[episode.shots[0].id]:{status:'approved',approvedRevision:1}}};const clip={...before.audioClips[0],asset:'new-audio',duration:2,end:2,mouth:[{time:0,shape:'round' as const,viseme:'O' as const},{time:2,shape:'rest' as const,viseme:'REST' as const}]};const history=new TransactionHistory<typeof state>();const next=replaceDialogueVoice(state,clip,voice,assets,24,1);history.commit(state);assert.equal(next.model.seconds,before.seconds+1);assert.equal(next.model.production!.studio!.shots[episode.shots[0].id].status,'draft');assert.ok(adaptPresentation(next.model).shots[0].duration>episode.shots[0].duration);assert.ok(next.model.actorAnimations!.KILLE.tracks.some(t=>t.key==='MOUTH_O'&&t.frames[0]?.opacity===1));assert.equal(before.audioClips[0].duration,1);const restored=history.undo(next)!;assert.equal(restored.model.seconds,before.seconds);assert.equal(restored.voices['new-audio'],undefined);assert.equal(history.redo(restored)!.model.audioClips.find(c=>c.dialogue===clip.dialogue)!.asset,'new-audio');});
test('locked timing and stale revisions reject the whole dialogue transaction',async()=>{const {state,voice,assets}=await fixture();const before=canonicalJson(state.model),clip={...state.model.audioClips[0],duration:3,end:3,mouth:[{time:0,shape:'rest' as const}]};assert.throws(()=>replaceDialogueVoice(state,clip,voice,assets,24,2),/muuttui/);state.model.events.find(e=>e.id===clip.dialogue)!.locked=true;assert.throws(()=>replaceDialogueVoice(state,clip,voice,assets,24,1),/Lukittu/);assert.equal(state.voices['new-audio'],undefined);delete state.model.events.find(e=>e.id===clip.dialogue)!.locked;assert.equal(canonicalJson(state.model),before);});
test('studio metadata, identity and original voice resources roundtrip in existing hahmo v5',async()=>{const {r,state,assets}=await fixture();state.model.production??=initProduction(state.model);state.model.production.studio=studioMetadata(state.model);state.model.production.studio.rawScript='Unparsed draft';const bytes=await saveProject({...r.doc,presentationAssets:assets,presentationAudio:state.voices},{...r.animation,duration:Math.ceil(state.model.seconds*24)},undefined,{...r.scene,presentationDraft:state.model});const loaded=await readProject(bytes);assert.equal(loaded.scene.presentationDraft!.production!.studio!.rawScript,'Unparsed draft');assert.equal(adaptPresentation(loaded.scene.presentationDraft!).id,adaptPresentation(state.model).id);assert.equal(Object.keys(loaded.doc.presentationAudio!).length,2);});
test('render manifest hashes resources and produces the same revision for repeated identical renders',async()=>{const r=await pack(),preset={id:'test',name:'test',format:'png' as const,width:1080,height:1920,fps:24,start:0,end:2/24,quality:8,transparent:true,audio:false,loop:0},a=new Uint8Array(await(await saveProject(r.doc,r.animation,undefined,r.scene)).arrayBuffer()),first=await inspectRenderSnapshot(a,preset),second=await inspectRenderSnapshot(a,preset);assert.deepEqual(first,second);assert.equal(first.expectedFrames,2);assert.ok(first.assets.every(a=>/^[a-f0-9]{64}$/.test(a.sha256)));assert.equal(first.snapshotHash,await sha256(a));const repacked=new Uint8Array(zipSync(unzipSync(a),{level:0,mtime:new Date('2020-01-01T00:00:00Z')}));const repeated=await inspectRenderSnapshot(repacked,preset);assert.equal(repeated.revisionId,first.revisionId);assert.notEqual(repeated.snapshotHash,first.snapshotHash);await assert.rejects(inspectRenderSnapshot(a,{...preset,end:10}),/keston/);assert.equal(canonicalJson({z:1,a:2}),canonicalJson({a:2,z:1}));});
test('render preflight rejects missing dialogue even if a previous mixed master exists',async()=>{const {r,state,assets,voice}=await fixture();state.model.audioClips=[];const scene={...r.scene,presentations:[state.model]},blob=await saveProject({...r.doc,presentationAssets:assets},{...r.animation,duration:120},voice,scene),preset={id:'test',name:'test',format:'mp4' as const,width:1080,height:1920,fps:24,start:0,end:5,quality:8,transparent:false,audio:true,loop:0};await assert.rejects(inspectRenderSnapshot(new Uint8Array(await blob.arrayBuffer()),preset),/repliikkiääni puuttuu/);});

test('resource manifest detects corrupted bytes before decoding and keeps legacy archives readable',async()=>{const r=await pack(),bytes=new Uint8Array(await(await saveProject(r.doc,r.animation,undefined,r.scene)).arrayBuffer()),files=unzipSync(bytes);assert.ok(files['resource-manifest.json']);const path=Object.keys(files).find(p=>p.startsWith('images/'))!;files[path][files[path].length-1]^=1;await assert.rejects(readProject(new Blob([new Uint8Array(zipSync(files))])),/resurssi.*muuttunut/);delete files['resource-manifest.json'];await readProject(new Blob([new Uint8Array(zipSync(files))]));});
test('scene renaming preserves identity through surviving event IDs',async()=>{const {state}=await fixture(),before=state.model;before.production??=initProduction(before);before.production.studio=studioMetadata(before);const after=structuredClone(before);after.sections=after.sections.map(s=>({...s,id:'renamed-'+s.id,name:'Renamed'}));after.events=after.events.map(e=>({...e,section:'renamed-'+e.section}));after.production!.studio=revise(before,after,'rename');assert.deepEqual(adaptPresentation(after).scenes.map(s=>s.id),adaptPresentation(before).scenes.map(s=>s.id));assert.deepEqual(adaptPresentation(after).shots.map(s=>s.id),adaptPresentation(before).shots.map(s=>s.id));});

test('autosave roundtrips unfinished and lengthened drafts without relaxing committed scene validation',async()=>{const {r,state}=await fixture(),draft=structuredClone(state.model);draft.startFrame=0;const doc=r.doc,animation={...r.animation,duration:2},blob=await saveProject(doc,animation,undefined,{...r.scene,presentationDraft:draft,presentationSource:'Not parsed yet'});const restored=await readProject(blob);assert.equal(restored.scene.presentationDraft!.audioClips.length,2);assert.equal(restored.scene.presentationSource,'Not parsed yet');assert.equal(restored.doc.presentationAssets,undefined);const committed=await saveProject(doc,animation,undefined,{...r.scene,presentations:[draft]});await assert.rejects(readProject(committed),/hahmo puuttuu/);});

test('board and validation navigation resolve a shared event selection and scene-local playhead',async()=>{const {state}=await fixture(),p=state.model,shots=adaptPresentation(p).shots;assert.ok(shots.every(s=>s.duration>0));const shot=shots[1],nav=selectShot(p,shot.id,24);assert.equal(nav.frame,Math.round(seconds(shot.at)*24));assert.equal(nav.eventId,shot.sourceEventId);const line=shot.eventIds.find(id=>p.events.find(e=>e.id===id)?.kind==='dialogue')!;assert.equal(selectShot(p,shot.id,24,line).eventId,line);assert.throws(()=>selectShot(p,shot.id,24,'not-a-member'),/kuulu/);assert.throws(()=>selectShot(p,'missing',24),/löydy/);});

test('reusing a renamed scene key creates a new identity rather than colliding with the preserved scene',async()=>{const {state}=await fixture(),before=state.model;before.production??=initProduction(before);before.production.studio=studioMetadata(before);const after=structuredClone(before),original=before.events[0].section;after.events=after.events.map(e=>({...e,section:'renamed'}));after.events.push({...before.events[0],id:'new-event',section:original,at:before.seconds,duration:1});after.seconds+=1;after.production!.studio=revise(before,after,'rename and append');const scenes=adaptPresentation(after).scenes;assert.equal(scenes.length,2);assert.equal(new Set(scenes.map(s=>s.id)).size,2);assert.equal(scenes[0].id,adaptPresentation(before).scenes[0].id);});

test('a newly inserted scene cannot steal the identity of a renamed existing scene',async()=>{const {state}=await fixture(),before=state.model;before.production??=initProduction(before);before.production.studio=studioMetadata(before);const after=structuredClone(before),original=before.events[0].section;after.events=[{...before.events[0],id:'new-first-event',section:original,at:0,duration:1},...after.events.map(e=>({...e,section:'renamed',at:(e.at??0)+1}))];after.seconds+=1;after.production!.studio=revise(before,after,'insert and rename');const old=adaptPresentation(before).scenes[0].id,scenes=adaptPresentation(after).scenes;assert.notEqual(scenes[0].id,old);assert.equal(scenes[1].id,old);});


test('review approval and lock are transactional, unlocking invalidates approval and content edits invalidate approved shots',async()=>{const {state,assets}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0];const approved=reviewShot(p,shot.id,'approve',1);assert.equal(adaptPresentation(approved).shots[0].status,'approved');assert.equal(studioMetadata(approved).revision,1);const locked=reviewShot(approved,shot.id,'lock',1);assert.equal(adaptPresentation(locked).shots[0].status,'locked');assert.throws(()=>editProduction(locked,{...locked,metadata:{...locked.metadata,title:'Changed'}},assets,24,1),/lukittu/);const unlocked=reviewShot(locked,shot.id,'unlock',1);assert.equal(adaptPresentation(unlocked).shots[0].status,'draft');const next=editProduction(approved,{...approved,metadata:{...approved.metadata,title:'Edited'}},assets,24,1);assert.equal(studioMetadata(next).revision,2);assert.equal(adaptPresentation(next).shots[0].status,'draft');const history=new TransactionHistory<Presentation>();history.commit(approved);assert.deepEqual(history.undo(next),approved);assert.equal(adaptPresentation(p).shots[0].status,'draft');});
test('approval rejects missing audio, failed validation, stale revision and illegal review transitions',async()=>{const {state}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0];assert.throws(()=>reviewShot(p,shot.id,'lock',1),/Hyväksy/);assert.throws(()=>reviewShot(p,shot.id,'approve',2),/muuttui/);assert.throws(()=>reviewShot({...p,audioClips:[]},shot.id,'approve',1),/äänet/);assert.throws(()=>reviewShot({...p,diagnostics:[{code:'missing',severity:'error',message:'Broken'}]},shot.id,'approve',1),/virheet/);});


test('a later camera edit preserves an earlier locked shot and only invalidates dependent approvals',async()=>{const {state,assets}=await fixture(),p=state.model,shots=adaptPresentation(p).shots;let approved=reviewShot(p,shots[0].id,'approve',1);approved=reviewShot(approved,shots[1].id,'approve',1);const locked=reviewShot(approved,shots[0].id,'lock',1),proposal=structuredClone(locked),id=shots[1].sourceEventId;proposal.production!.cameras[id]={...proposal.production!.cameras[id],zoom:.2};const next=editProduction(locked,proposal,assets,24,1),result=adaptPresentation(next).shots;assert.equal(result[0].status,'locked');assert.equal(result[1].status,'draft');assert.equal(next.production!.studio!.shots[shots[0].id].approvedRevision,2);assert.equal(studioMetadata(locked).revision,1);assert.equal(adaptPresentation(locked).shots[1].status,'approved');});
test('earlier dialogue retiming cannot shift a later locked shot and rejection preserves audio and approval',async()=>{const {state,assets,voice}=await fixture(),p=state.model,shots=adaptPresentation(p).shots,locked=reviewShot(reviewShot(p,shots[1].id,'approve',1),shots[1].id,'lock',1),before=canonicalJson(locked),clip={...locked.audioClips[0],asset:'longer',duration:2,end:2};assert.throws(()=>replaceDialogueVoice({...state,model:locked},clip,voice,assets,24,1),/lukittu/);assert.equal(canonicalJson(locked),before);assert.equal(state.voices.longer,undefined);});
test('global framing and deletion remain blocked when they affect a locked shot',async()=>{const {state,assets}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0],locked=reviewShot(reviewShot(p,shot.id,'approve',1),shot.id,'lock',1);assert.throws(()=>editProduction(locked,{...locked,world:{...locked.world,width:1920}},assets,24,1),/lukittu/);const proposal=structuredClone(locked);proposal.events=proposal.events.filter(e=>e.id!==shot.sourceEventId);assert.throws(()=>editProduction(locked,proposal,assets,24,1),/lukittu/);});


test('interpolation beyond a shot boundary and animation truncation remain protected dependencies',async()=>{const {state}=await fixture(),p=structuredClone(state.model),shots=adaptPresentation(p).shots,a=p.actorAnimations!.KILLE,boundary=seconds(shots[0].at+shots[0].duration)*a.fps;const pose={x:0,y:0,rotation:0,scale:1,opacity:1,easing:'linear' as const};a.tracks=[{key:'controlled',frames:[{...pose,frame:0},{...pose,frame:Math.ceil(boundary)+10,x:10}]}];const changed=structuredClone(p);changed.actorAnimations!.KILLE.tracks[0].frames[1].x=20;assert.ok(affectedShots(p,changed).has(shots[0].id));const truncated=structuredClone(p);truncated.actorAnimations!.KILLE.duration=1;assert.ok(affectedShots(p,truncated).has(shots[0].id));});


test('review comments persist in hahmo, block approval while open, resolve and reopen in one undo transaction',async()=>{const {state,r,assets}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0],withComment=commentProduction(p,{kind:'add',shotId:shot.id,offset:0,body:'  Tarkista käden liike.  '},1),comment=studioMetadata(withComment).reviewComments![0];assert.equal(comment.body,'Tarkista käden liike.');assert.equal(studioMetadata(withComment).revision,1);assert.equal(studioMetadata(p).reviewComments,undefined);assert.throws(()=>reviewShot(withComment,shot.id,'approve',1),/kommentit/);const resolved=commentProduction(withComment,{kind:'resolve',id:comment.id},1),approved=reviewShot(resolved,shot.id,'approve',1),reopened=commentProduction(approved,{kind:'reopen',id:comment.id},1);assert.equal(adaptPresentation(reopened).shots[0].status,'draft');assert.equal(studioMetadata(reopened).reviewComments![0].resolvedAt,undefined);const history=new TransactionHistory<Presentation>();history.commit(approved);assert.deepEqual(history.undo(reopened),approved);const bytes=await saveProject({...r.doc,presentationAssets:assets,presentationAudio:state.voices},{...r.animation,duration:Math.ceil(p.seconds*24)},undefined,{...r.scene,presentationDraft:resolved});const loaded=await readProject(bytes);assert.deepEqual(studioMetadata(loaded.scene.presentationDraft!).reviewComments,studioMetadata(resolved).reviewComments);});
test('comment navigation follows shot retiming, clamps shortened shots and preserves orphan feedback',async()=>{const {state}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[1],annotated=commentProduction(p,{kind:'add',shotId:shot.id,offset:Math.floor(shot.duration*.9),body:'Tarkista tämä kohta.'},1),comment=studioMetadata(annotated).reviewComments![0],before=commentNavigation(annotated,comment,24)!;const retimed=structuredClone(annotated);retimed.events=retimed.events.map(e=>({...e,at:(e.at??0)+1}));retimed.seconds+=1;assert.equal(commentNavigation(retimed,comment,24)!.frame,before.frame+24);const shorter=structuredClone(annotated);shorter.seconds=seconds(shot.at)+.1;shorter.events=shorter.events.map(e=>({...e,duration:Math.min(e.duration??0,.1)}));assert.equal(commentNavigation(shorter,comment,24)!.clamped,true);assert.ok(commentNavigation(shorter,comment,24)!.frame<Math.ceil(shorter.seconds*24));const removed=structuredClone(annotated);removed.events=removed.events.filter(e=>e.id!==shot.sourceEventId);assert.equal(commentNavigation(removed,comment,24),null);assert.equal(studioMetadata(removed).reviewComments![0].body,comment.body);});
test('comments on approved shots invalidate only their approval; locked content remains locked while feedback is handled',async()=>{const {state}=await fixture(),p=state.model,shots=adaptPresentation(p).shots,approved=reviewShot(reviewShot(p,shots[0].id,'approve',1),shots[1].id,'approve',1),annotated=commentProduction(approved,{kind:'add',shotId:shots[0].id,offset:0,body:'Korjauspyyntö'},1);assert.equal(adaptPresentation(annotated).shots[0].status,'draft');assert.equal(adaptPresentation(annotated).shots[1].status,'approved');const locked=reviewShot(approved,shots[0].id,'lock',1),lockedNote=commentProduction(locked,{kind:'add',shotId:shots[0].id,offset:0,body:'Huomio lukittuun kuvaan'},1);assert.equal(adaptPresentation(lockedNote).shots[0].status,'locked');const fixed=commentProduction(lockedNote,{kind:'resolve',id:studioMetadata(lockedNote).reviewComments![0].id},1);assert.equal(adaptPresentation(fixed).shots[0].status,'locked');});
test('malformed, oversized, stale and out-of-shot review data is rejected without mutating the model',async()=>{const {state}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0],before=canonicalJson(p);assert.throws(()=>commentProduction(p,{kind:'add',shotId:shot.id,offset:shot.duration,body:'Outside'},1),/sisällä/);assert.throws(()=>commentProduction(p,{kind:'add',shotId:shot.id,offset:0,body:'x'.repeat(4001)},1),/4000/);assert.throws(()=>commentProduction(p,{kind:'add',shotId:shot.id,offset:0,body:'stale'},2),/muuttui/);const note=studioMetadata(commentProduction(p,{kind:'add',shotId:shot.id,offset:0,body:'valid'},1)).reviewComments![0];assert.throws(()=>validateReviewComments([note,note],1));assert.throws(()=>validateReviewComments([{...note,status:'resolved'}],1));assert.throws(()=>readStudio({...studioMetadata(p),reviewComments:[{...note,offset:-1}]}));assert.throws(()=>validateReviewComments(Array(1001).fill(note),1));assert.equal(canonicalJson(p),before);});


test('production overview counts distinct shots, keeps review readiness separate from approval and never mutates data',async()=>{const {state}=await fixture(),p=state.model,before=canonicalJson(p),overview=productionOverview(p);assert.equal(overview.counts.all,2);assert.equal(overview.counts.ready,2);assert.equal(overview.counts.approved,0);assert.equal(overview.counts.attention,0);const shots=overview.episode.shots,approved=reviewShot(p,shots[0].id,'approve',1),locked=reviewShot(approved,shots[0].id,'lock',1),annotated=commentProduction(locked,{kind:'add',shotId:shots[0].id,offset:0,body:'Palautetta'},1),result=productionOverview(annotated);assert.equal(result.counts.locked,1);assert.equal(result.counts.attention,1);assert.equal(result.counts.comments,1);assert.equal(result.counts.ready,1);assert.equal(result.counts.draft+result.counts.approved+result.counts.locked,result.counts.all);assert.equal(canonicalJson(p),before);});
test('production filters combine status, comments, missing voice references and Finnish character/scene search',async()=>{const {state}=await fixture(),p=state.model,shots=adaptPresentation(p).shots,missing={...p,audioClips:p.audioClips.filter(c=>c.dialogue!==p.events.find(e=>shots[1].eventIds.includes(e.id)&&e.kind==='dialogue')!.id)},overview=productionOverview(missing);assert.equal(filterProductionShots(overview,'missingAudio').length,1);assert.equal(filterProductionShots(overview,'attention').length,1);assert.equal(filterProductionShots(overview,'ready').length,1);assert.equal(filterProductionShots(overview,'all',' kille ').length,2);assert.equal(filterProductionShots(overview,'all',overview.episode.scenes[0].name.toLocaleUpperCase('fi-FI')).length,2);assert.equal(filterProductionShots(overview,'approved').length,0);assert.equal(filterProductionShots(overview,'all','does-not-exist').length,0);});
test('next unfinished navigation wraps, includes feedback on locked shots and returns none when all have no outstanding work',async()=>{const {state}=await fixture(),p=state.model,shots=adaptPresentation(p).shots,approved=reviewShot(reviewShot(p,shots[0].id,'approve',1),shots[1].id,'approve',1);assert.equal(nextUnfinishedShot(productionOverview(approved)),undefined);assert.equal(nextUnfinishedShot(productionOverview(p),shots[0].id)!.id,shots[1].id);assert.equal(nextUnfinishedShot(productionOverview(p),shots[1].id)!.id,shots[0].id);const locked=reviewShot(approved,shots[0].id,'lock',1),noted=commentProduction(locked,{kind:'add',shotId:shots[0].id,offset:0,body:'Huomio'},1);assert.equal(nextUnfinishedShot(productionOverview(noted),shots[1].id)!.id,shots[0].id);});
