test('shot assignments roundtrip in hahmo, preserve approval and locks, and undo removes the entire scheduling transaction',async()=>{const {state,r,assets}=await fixture(),p=state.model,shot=adaptPresentation(p).shots[0],locked=reviewShot(reviewShot(p,shot.id,'approve',1),shot.id,'lock',1),assigned=assignShotTask(locked,{shotId:shot.id,owner:'  Aleksi  ',dueDate:'2026-10-05'},1);assert.equal(studioMetadata(assigned).shotTasks![shot.id].owner,'Aleksi');assert.equal(adaptPresentation(assigned).shots[0].status,'locked');assert.equal(studioMetadata(assigned).revision,1);assert.equal(studioMetadata(locked).shotTasks,undefined);const history=new TransactionHistory<Presentation>();history.commit(locked);assert.deepEqual(history.undo(assigned),locked);const bytes=await saveProject({...r.doc,presentationAssets:assets,presentationAudio:state.voices},{...r.animation,duration:Math.ceil(p.seconds*24)},undefined,{...r.scene,presentationDraft:assigned});const restored=await readProject(bytes);assert.deepEqual(studioMetadata(restored.scene.presentationDraft!).shotTasks,studioMetadata(assigned).shotTasks);const cleared=assignShotTask(assigned,{shotId:shot.id,owner:'',dueDate:''},1);assert.deepEqual(studioMetadata(cleared).shotTasks,{});});
