 const assigned=assignShotTasks(state.model,{shotIds:ids,owner:'Aleksi',dueDate:'2026-10-05'},1),history=new TransactionHistory<Presentation>();history.commit(state.model);assert.deepEqual(history.undo(assigned),state.model);assert.deepEqual(history.redo(state.model),assigned);
 const commented=commentProduction(assigned,{kind:'add',shotId:ids[0],offset:0,body:'Tarkista ajoitus'},1);assert.throws(()=>reviewShot(commented,ids[0],'approve',1));
