test('content-addressed audio restoration checks SHA-256, preserves approval and is atomic with undo',async()=>{const {state,assets,voice}=await fixture(),digest='audio-'+await sha256(new Uint8Array(await voice.blob.arrayBuffer())),model=structuredClone(state.model);model.audioClips[0].asset=digest;const id=adaptPresentation(model).shots[0].id,approved=reviewShot(model,id,'approve',1),missing={model:approved,voices:{'audio-1':voice}};assert.ok(productionResources(missing,assets).some(r=>!r.available));assert.equal(await verifyAudioRelink(digest,voice),voice);await assert.rejects(verifyAudioRelink(digest,{name:'same.wav',blob:new Blob([new Uint8Array([9])])}),/ei ole alkuperäinen/);await assert.rejects(verifyAudioRelink('legacy-id',voice),/SHA-256/);const next=journalProductionCommand(missing,{...missing,voices:{...missing.voices,[digest]:voice}},'relink-audio');assert.equal(adaptPresentation(next.model).shots[0].status,'approved');assert.deepEqual(next.model.audioClips,approved.audioClips);assert.equal(studioMetadata(next.model).revision,1);assert.ok(productionResources(next,assets).every(r=>r.available));const history=new TransactionHistory<ProductionState>();history.commit(missing);const undo=history.undo(next)!;assert.equal(undo.voices[digest],undefined);assert.ok(history.redo(undo)!.voices[digest]);});
