test('bind-cast command journals speaker hahmo attachment',async()=>{const {state,assets}=await fixture(),speaker=state.model.characters[0]!,before=studioMetadata(state.model).revision,next=executeProductionCommand(state,{kind:'bind-cast',speaker,assetId:'kille'},assets,24,before);assert.equal(studioMetadata(next.model).commandJournal!.at(-1)!.kind,'bind-cast');assert.equal(next.model.bindings.find(b=>b.speaker===speaker)?.asset,'kille');assert.equal(studioMetadata(next.model).revision,before+1);});

test('central production commands cover edit, voice, scheduling, comments and review with bounded validated history',async()=>{const {state,assets,voice}=await fixture();let next=executeProductionCommand(state,{kind:'edit',proposal:{...state.model,metadata:{...state.model.metadata,title:'Command edited'}}},assets,24,1);const revision=studioMetadata(next.model).revision,id=adaptPresentation(next.model).shots[0].id;assert.equal(revision,2);next=executeProductionCommand(next,{kind:'task',command:{shotId:id,owner:'Aleksi',dueDate:''}},assets,24,revision);next=executeProductionCommand(next,{kind:'comment',command:{kind:'add',shotId:id,offset:0,body:'Check'}},assets,24,revision);const comment=studioMetadata(next.model).reviewComments![0];next=executeProductionCommand(next,{kind:'comment',command:{kind:'resolve',id:comment.id}},assets,24,revision);next=executeProductionCommand(next,{kind:'voice',clip:next.model.audioClips[0],voice},assets,24,revision);assert.deepEqual(studioMetadata(next.model).commandJournal!.map(e=>e.kind),['edit','task','comment','comment','voice']);for(let i=0;i<105;i++)next=journalProductionCommand(next,next,'relink-audio');assert.equal(studioMetadata(next.model).commandJournal!.length,100);const meta=studioMetadata(next.model);assert.throws(()=>readStudio({...meta,commandJournal:[{...meta.commandJournal![0],revisionAfter:meta.revision+1}]}));});

test('character package relink preserves layer-bound animation, retains old asset and undo restores entire resource state',async()=>{const {state,assets,r}=await fixture(),id=adaptPresentation(state.model).shots[0].id,approved={...state,model:reviewShot(state.model,id,'approve',1),assets},key='cast-sha256-'+'a'.repeat(64),before=canonicalJson(approved.model),next=relinkCharacter(approved,assets,'KILLE',key,{doc:{...r.doc,name:'Updated art'},animation:r.animation},24);assert.equal(next.model.bindings[0].asset,key);assert.ok(next.assets!.kille);assert.deepEqual(next.assets![key].animation.tracks,r.animation.tracks);assert.equal(adaptPresentation(next.model).shots[0].status,'draft');assert.equal(canonicalJson(approved.model),before);const history=new TransactionHistory<ProductionState>(30,s=>({...s,model:structuredClone(s.model),voices:{...s.voices}}));history.commit(approved);const undo=history.undo(next)!;assert.equal(undo.model.bindings[0].asset,'kille');assert.equal(undo.assets![key],undefined);assert.equal(history.redo(undo)!.model.bindings[0].asset,key);});
test('incompatible character rig and locked resource replacement fail without overwriting old resources',async()=>{const {state,assets,r}=await fixture(),id=adaptPresentation(state.model).shots[0].id,locked={...state,model:reviewShot(reviewShot(state.model,id,'approve',1),id,'lock',1)},key='cast-sha256-'+'b'.repeat(64),before=canonicalJson(locked.model);assert.throws(()=>relinkCharacter(locked,assets,'KILLE',key,{doc:r.doc,animation:r.animation},24),/lukittu/);assert.throws(()=>relinkCharacter(state,assets,'KILLE',key,{doc:{...r.doc,width:r.doc.width+1},animation:r.animation},24));assert.equal(canonicalJson(locked.model),before);assert.equal(Object.hasOwn(assets,key),false);});
test('editor edit boundary validates rig and animation together before any commit',async()=>{const {r}=await fixture(),before=canonicalJson(r.animation),next=prepareEditorEdit(r.doc,r.animation.rig,r.animation);assert.deepEqual(next.animation.tracks,r.animation.tracks);assert.equal(canonicalJson(r.animation),before);const rig=structuredClone(r.animation.rig);rig.parts[0].parentKey=rig.parts[0].key;assert.throws(()=>prepareEditorEdit(r.doc,rig,r.animation),/kehä/);assert.throws(()=>prepareEditorEdit(r.doc,r.animation.rig,{...r.animation,tracks:[{key:'orphan',frames:[]}]}));});

test('explicit PSD layer mapping preserves parent links, pivots, tracks and quick roles without guessing names',async()=>{const {r,state,assets}=await fixture();r.animation.tracks=[{key:r.doc.quick!.roles.root,frames:[{frame:0,x:3,y:4,rotation:5,scale:1,opacity:1,easing:'hold'}]}];const doc=structuredClone(r.doc),mapping:Record<string,string>={};for(const n of flatten(doc.layers)){mapping[n.key]='new'+n.key;n.key='new'+n.key;n.path='Revision/'+n.path;delete n.psdId;}delete doc.quick;const id='cast-sha256-'+'d'.repeat(64),incoming={doc,animation:r.animation};assert.throws(()=>relinkCharacter(state,assets,'KILLE',id,incoming,24));const next=relinkCharacter(state,assets,'KILLE',id,incoming,24,mapping),pack=next.assets[id];for(const p of r.animation.rig.parts){const mapped=pack.animation.rig.parts.find(n=>n.key===mapping[p.key])!;assert.deepEqual(mapped.pivot,p.pivot);if(p.parentKey)assert.equal(mapped.parentKey,mapping[p.parentKey]);}for(const t of r.animation.tracks)assert.deepEqual(pack.animation.tracks.find(n=>n.key===mapping[t.key])?.frames,t.frames);assert.equal(pack.doc.quick!.roles.root,mapping[r.doc.quick!.roles.root]);assert.equal(Object.hasOwn(assets,id),false);assert.equal(next.assets.kille,assets.kille);});
test('manual mapping rejects missing or duplicate targets and supports resized raw PSD',async()=>{const {r,state,assets}=await fixture(),doc=structuredClone(r.doc),mapping=Object.fromEntries(r.animation.rig.parts.map(p=>[p.key,p.key])),id='cast-sha256-'+'e'.repeat(64),before=canonicalJson(state.model);const [a,b]=Object.keys(mapping);const missing={...mapping};delete missing[a];assert.throws(()=>relinkCharacter(state,assets,'KILLE',id,{doc,animation:r.animation},24,missing));assert.throws(()=>relinkCharacter(state,assets,'KILLE',id,{doc,animation:r.animation},24,{...mapping,[a]:mapping[b]}));const resized=relinkCharacter(state,assets,'KILLE',id,{doc:{...doc,quick:undefined,width:doc.width+1},animation:r.animation},24,mapping);assert.equal(resized.assets[id].animation.rig.source.width,doc.width+1);assert.equal(canonicalJson(state.model),before);assert.equal(Object.hasOwn(assets,id),false);});
